<?php
declare(strict_types=1);
require dirname(__DIR__).'/private/AccountStore.php';
if(getenv('OSMON_TEST_DATABASE')!=='osmon_test')exit(1);
$c=['host'=>getenv('OSMON_TEST_HOST')?:'127.0.0.1','port'=>(int)(getenv('OSMON_TEST_PORT')?:3306),'database'=>'osmon_test','username'=>getenv('OSMON_TEST_USER')?:'root','password'=>getenv('OSMON_TEST_PASSWORD')?:'test-only'];
$db=connectFamily($c);$now=1000000.0;$mail=[];$pass='Test-only-password-123';$clock=static function()use(&$now){return$now;};
$a=new AccountStore($db,'https://parents.example.test',static function(...$v)use(&$mail){$mail[]=$v;},$clock);$a->install();$f=new FamilyStore($db,$clock);
function yes(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}
function reject(int $status,Closure $fn):void{try{$fn();}catch(FamilyAPIError $e){yes($e->status===$status);return;}throw new RuntimeException('Expected rejection '.$status);}
function req(string $action,array $body=[],string $token=''):array{global$a;return$a->dispatch('POST',$action,$token,$body);}
function code():string{global$mail;preg_match('/#account-(?:verify|reset)=([A-Za-z0-9_-]{43})/',$mail[count($mail)-1][2],$m);return$m[1];}
function resetCase():void{global$db,$mail,$now;$db->exec('DELETE FROM osmon_parents');$mail=[];$now=1000000.0;}
function registerVerified():string{global$pass;req('register',['email'=>'Owner@Example.COM']);$v=code();req('verify',['code'=>$v,'password'=>$pass]);return req('login',['email'=>'owner@example.com','password'=>$pass])['token'];}
$tests=[];
$tests['register emails no password or token response and cannot login unverified']=function(){global$mail,$pass;resetCase();$r=req('register',['email'=>'Owner@Example.COM']);yes(!isset($r['token'])&&!isset($r['code'])&&count($mail)===1&&$mail[0][0]==='owner@example.com');reject(401,fn()=>req('login',['email'=>'owner@example.com','password'=>$pass]));};
$tests['confirmation password choice token one use and hashed storage']=function(){global$db,$pass;resetCase();req('register',['email'=>'owner@example.com']);$v=code();reject(400,fn()=>req('verify',['code'=>$v,'password'=>'short']));req('verify',['code'=>$v,'password'=>$pass]);reject(400,fn()=>req('verify',['code'=>$v,'password'=>$pass]));$t=req('login',['email'=>'owner@example.com','password'=>$pass])['token'];$dump=encodeJSON($db->query('SELECT * FROM osmon_accounts')->fetchAll());yes(!str_contains($dump,$pass)&&!str_contains($dump,$t)&&!str_contains($dump,$v));};
$tests['confirmation expires']=function(){global$now,$pass;resetCase();req('register',['email'=>'owner@example.com']);$v=code();$now+=86401;reject(400,fn()=>req('verify',['code'=>$v,'password'=>$pass]));};
$tests['adoption keeps children tasks completion and support id revokes old sessions']=function(){global$f,$a,$db,$pass;resetCase();$old=$f->dispatch('POST','/v1/parents','',[])['token'];$pair=$f->dispatch('POST','/v1/pairings','',['name'=>'Testgerät','config'=>['limit'=>1,'tasks'=>[['id'=>newUUID(),'title'=>'Testaufgabe','repeat'=>'daily']]]]);$f->dispatch('POST','/v1/claims',$old,['code'=>$pair['code']]);$before=$f->dispatch('GET','/v1/children',$old,[])['children'];$webcode=$f->dispatch('POST','/v1/web-codes',$old,[])['code'];$web=$f->dispatch('POST','/v1/web-codes/redeem','',['code'=>$webcode])['token'];$db->prepare('UPDATE osmon_parents SET public_id=? WHERE token=?')->execute(['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',tokenHash($old)]);req('register',['email'=>'owner@example.com'],$web);req('verify',['code'=>code(),'password'=>$pass]);$new=req('login',['email'=>'owner@example.com','password'=>$pass])['token'];yes($f->dispatch('GET','/v1/children',$new,[])['children']===$before);foreach([$old,$web]as$t)reject(401,fn()=>$f->dispatch('GET','/v1/children',$t,[]));yes($f->dispatch('GET','/v1/device',$pair['token'],[])['paired']);yes($db->query('SELECT public_id FROM osmon_parents')->fetchColumn()==='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');};
$tests['existing email cannot overwrite password or move family']=function(){global$f,$pass;resetCase();$t=registerVerified();$other=$f->dispatch('POST','/v1/parents','',[])['token'];$r=req('register',['email'=>'owner@example.com'],$other);yes($r['ok']);yes(req('login',['email'=>'owner@example.com','password'=>$pass])['token']!==$t);};
$tests['password reset rejects replay old credentials sessions and web codes']=function(){global$now,$pass,$f;resetCase();$old=registerVerified();$webcode=$f->dispatch('POST','/v1/web-codes',$old,[])['code'];$now+=61;req('forgot',['email'=>'owner@example.com']);$v=code();req('reset',['code'=>$v,'password'=>'New-test-password-456']);reject(400,fn()=>req('reset',['code'=>$v,'password'=>$pass]));reject(401,fn()=>req('login',['email'=>'owner@example.com','password'=>$pass]));reject(401,fn()=>$f->dispatch('GET','/v1/children',$old,[]));reject(404,fn()=>$f->dispatch('POST','/v1/web-codes/redeem','',['code'=>$webcode]));yes(isset(req('login',['email'=>'owner@example.com','password'=>'New-test-password-456'])['token']));};
$tests['reset expires and wrong purpose fails']=function(){global$now,$pass;resetCase();registerVerified();$now+=61;req('forgot',['email'=>'owner@example.com']);$v=code();reject(400,fn()=>req('verify',['code'=>$v,'password'=>$pass]));$now+=1801;reject(400,fn()=>req('reset',['code'=>$v,'password'=>$pass]));};
$tests['generic mail responses and cooldown hourly cap']=function(){global$mail,$now;resetCase();$unknown=req('forgot',['email'=>'absent@example.com']);req('register',['email'=>'owner@example.com']);$known=req('resend',['email'=>'owner@example.com']);yes($known===$unknown&&count($mail)===1);for($i=0;$i<6;$i++){$now+=61;req('resend',['email'=>'owner@example.com']);}yes(count($mail)===5);};
$tests['failed login counters persist then unlock']=function(){global$now,$pass;resetCase();registerVerified();for($i=0;$i<5;$i++)reject(401,fn()=>req('login',['email'=>'owner@example.com','password'=>'wrong']));reject(401,fn()=>req('login',['email'=>'owner@example.com','password'=>$pass]));$now+=901;yes(isset(req('login',['email'=>'owner@example.com','password'=>$pass])['token']));};
$tests['suspension blocks login and reset']=function(){global$db,$now,$pass;resetCase();registerVerified();$now+=61;req('forgot',['email'=>'owner@example.com']);$v=code();$db->exec('UPDATE osmon_parents SET suspended=1');reject(401,fn()=>req('login',['email'=>'owner@example.com','password'=>$pass]));reject(400,fn()=>req('reset',['code'=>$v,'password'=>$pass]));};
$tests['account family survives former 90 day deadline and sessions expire']=function(){global$now,$f,$pass;resetCase();$t=registerVerified();$now+=91*86400;$f->cleanup();reject(401,fn()=>$f->dispatch('GET','/v1/children',$t,[]));yes(isset(req('login',['email'=>'owner@example.com','password'=>$pass])['token']));};
$tests['family deletion cascades account and tokens']=function(){global$db,$f;resetCase();$t=registerVerified();$f->dispatch('DELETE','/v1/parents',$t,[]);yes((int)$db->query('SELECT count(*) FROM osmon_accounts')->fetchColumn()===0);yes((int)$db->query('SELECT count(*) FROM osmon_account_tokens')->fetchColumn()===0);};
$tests['account status is scoped and migration idempotent']=function(){global$a,$db;resetCase();$t=registerVerified();$a->install();yes($a->dispatch('GET','status',$t,[])['account']['verified']);reject(401,fn()=>$a->dispatch('GET','status','',[]));yes((int)$db->query('SELECT count(*) FROM osmon_accounts')->fetchColumn()===1);};
$failed=0;foreach($tests as$name=>$test){try{$test();echo"PASS $name\n";}catch(Throwable$e){$failed++;fwrite(STDERR,"FAIL $name: ".$e->getMessage()."\n");}}echo count($tests)." account tests, $failed failures\n";exit($failed?1:0);
